  const YENI_EK = {
    zikir: {
      kissa: { baslik: "Mûsâ'ya “zikrimde gevşemeyin”", metin: "Allah, Hz. Mûsâ ile kardeşi Hârûn'u, kendisini ilah ilan eden Firavun'a gönderirken onlara şöyle buyurur: “Sen ve kardeşin âyetlerimle gidin ve beni anmakta gevşek davranmayın” (Tâhâ 42). Dünyanın en güçlü zalimiyle yüzleşmeye giden iki peygambere verilen azık, zikirdir. Hz. Mûsâ da görevini alırken Allah'tan, kardeşinin kendisine yardımcı olmasını şu gerekçeyle istemişti: “Seni çokça tesbih edelim ve seni çokça analım” (Tâhâ 33-34)." },
      hadisler: [["Rabbini anan ile anmayanın durumu, diri ile ölünün durumu gibidir.", "Buhârî"], ["Size amellerinizin en hayırlısını, Rabbiniz katında en temiz olanını ve derecelerinizi en çok yükselteni haber vereyim mi? ... Allah'ı zikretmektir.", "Tirmizî, İbn Mâce"]],
      sozler: [{ alim: "ibnulkayyim", metin: "el-Vâbilü's-sayyib adlı eserinde zikrin yüzden fazla faydasını sayar ve zikri kalbin gıdası olarak tanımlar: Balık için su ne ise, kalp için de zikir odur." }, { alim: "nevevi", metin: "el-Ezkâr adlı eserinde, Hz. Peygamber'in gün boyunca, yemekte, yolculukta, uykuda ve sıkıntıda okuduğu zikirleri toplamıştır; eser, gündelik hayatın her anını bir zikre dönüştürmenin rehberidir." }],
      uygulama: "Gün içinde tekrar ettiğin bir işi (kapıdan çıkmak, yemeğe başlamak, telefonu eline almak gibi) seç ve onu kısa bir zikirle birleştirmeyi alışkanlık hâline getir." },
    sidk: {
      kissa: { baslik: "Safâ tepesindeki soru", metin: "Hz. Peygamber, açık davete başladığında Safâ tepesine çıkıp Kureyş kabilelerini çağırdı ve şöyle sordu: “Size, şu vadinin arkasında size saldırmak üzere bir süvari birliğinin olduğunu haber versem, bana inanır mısınız?” Hepsi “Evet, senden hiç yalan görmedik” dedi. Bunun üzerine “O hâlde ben sizi şiddetli bir azaptan önce uyaran biriyim” buyurdu (Buhârî). Davetin ilk dayanağı, kırk yıllık bir doğruluk hayatıydı." },
      hadisler: [["Doğruluk iyiliğe, iyilik de cennete götürür. Kişi doğru söylemeye devam ederek Allah katında sıddîk diye yazılır. Yalan kötülüğe, kötülük de cehenneme götürür.", "Buhârî, Müslim"], ["Münafığın alameti üçtür: Konuşunca yalan söyler, söz verince sözünden döner, kendisine bir şey emanet edilince ihanet eder.", "Buhârî, Müslim"]],
      sozler: [{ alim: "cuneyd", metin: "Doğru olanın günde kırk kez hâlden hâle girebileceğini, riyakârın ise kırk yıl tek bir hâlde kalabileceğini söylediği nakledilir; çünkü doğru olan kendi hâlini sürekli sorgular. (Kuşeyrî'nin Risâle'sinde nakledilir)" }, { alim: "gazali", metin: "İhyâ'da doğruluğun altı anlamını sayar: sözde, niyette, azimde, azmi yerine getirmede, amelde ve manevî makamlarda doğruluk." }],
      uygulama: "Bu hafta bir konuşmada, karşındakini memnun etmek için gerçeği biraz bükme isteği duyduğunda bunu fark et ve doğruyu yumuşak bir dille söylemeyi dene." },
    uhuvvet: {
      kissa: { baslik: "Sa'd b. Rebî' ve Abdurrahman b. Avf", metin: "Medine'de kardeş ilan edilen Sa'd b. Rebî', Mekke'den her şeyini bırakarak gelen kardeşi Abdurrahman b. Avf'a malının yarısını vermeyi teklif etti. Abdurrahman ise şöyle cevap verdi: “Allah malını ve aileni sana mübarek kılsın. Bana çarşının yolunu göster.” Çarşıda ticarete başladı ve kısa sürede kendi geçimini sağladı (Buhârî). Kıssa, kardeşlikte hem cömertliği hem de onurunu korumayı bir arada gösterir." },
      hadisler: [["Müminlerin birbirini sevmede, birbirine merhamet etmede ve birbirine şefkat göstermede misali bir beden gibidir: Bir organı rahatsız olduğunda bütün beden uykusuzluk ve ateşle ona katılır.", "Buhârî, Müslim"], ["Sizden biri, kendisi için istediğini kardeşi için de istemedikçe iman etmiş olmaz.", "Buhârî, Müslim"]],
      sozler: [{ alim: "gazali", metin: "İhyâ'nın “Âdâbü'l-ülfe ve'l-uhuvve” bölümünde kardeşliğin sekiz hakkını sayar: malla yardım, bizzat yardım, kardeşin kusurları hakkında susmak, onu güzel sözlerle anmak, affetmek, onun için dua etmek, vefa göstermek ve ona yük olmamak." }],
      uygulama: "Bu hafta bir kardeşinin bir ihtiyacını, o istemeden fark edip karşılamaya çalış veya onun gıyabında adıyla dua et." },
    infak: {
      kissa: { baslik: "Bahçe sahipleri", metin: "Kalem suresinde anlatılan bir kıssada, bir bahçeyi miras alan kardeşler, babalarının yaptığı gibi fakirlere pay vermemek için ürünü sabah erkenden, kimse görmeden toplamaya yemin ederler ve “inşallah” demezler. Gece bahçeye bir felaket isabet eder ve sabah geldiklerinde onu kapkara bulurlar. İçlerinden en makul olanı “Ben size tesbih etmeniz gerektiğini söylememiş miydim?” der; onlar da pişman olup tevbe ederler (Kalem 17-33). Kıssa, fakirin hakkını gizlemeye çalışmanın malı nasıl helak ettiğini anlatır." },
      hadisler: [["Sadaka malı eksiltmez.", "Müslim"], ["Her sabah iki melek iner. Biri “Allah'ım, infak edene yerine başkasını ver” der, diğeri “Allah'ım, cimrilik edenin malını telef et” der.", "Buhârî, Müslim"]],
      sozler: [{ alim: "gazali", metin: "İhyâ'nın “Esrârü'z-zekât” bölümünde zekâtın üç anlamını sayar: Allah sevgisini malla sınamak, cimrilik hastalığından arınmak ve mal nimetine şükretmek." }],
      uygulama: "Bu hafta küçük de olsa, sevdiğin bir şeyden, kimsenin bilmeyeceği şekilde bir ihtiyaç sahibine ver." },
    hikmet: {
      kissa: { baslik: "Lokmân'ın oğluna öğütleri", metin: "Lokmân suresinde, kendisine hikmet verilen Lokmân'ın oğluna öğütleri aktarılır: Allah'a ortak koşmamak, anne babaya iyilik etmek, en küçük bir amelin bile Allah'tan gizli kalmayacağını bilmek, namaz kılmak, iyiliği emredip kötülükten sakındırmak, başa gelene sabretmek, insanlara karşı böbürlenmemek, yürüyüşünde ölçülü olmak ve sesini alçaltmak (Lokmân 13-19). Bu öğütler, hikmetin akide, ibadet, ahlâk ve gündelik davranışı bir bütün hâlinde kapsadığını gösterir." },
      hadisler: [["İki kişiden başkasına gıpta edilmez: Allah'ın kendisine mal verip onu hak yolunda harcatan kişi ve Allah'ın kendisine hikmet verip onunla hükmeden ve onu öğreten kişi.", "Buhârî, Müslim"], ["Hikmetli söz müminin yitiğidir; onu nerede bulursa ona en layık olan odur.", "Tirmizî (senedi zayıf; manası âlimlerce kabul görmüştür)"]],
      sozler: [{ alim: "dihlevi", metin: "Hüccetullâhi'l-bâliğa'da şer'î hükümlerin hikmetlerini ve maslahatlarını açıklamayı bir ilim olarak sistemleştirir." }],
      uygulama: "Bu hafta bir konuşmada doğru bildiğin bir şeyi söylemeden önce, onu söylemenin zamanını, yerini ve dilini düşünmek için bir an dur." }
  };

